//
// The variable catalogue: every variable the account’s templates can use, with where each is used.
// System variables first, then global ones, then template variables, each sorted by name. Requires a
// full-access key. kind is system (filled by ZapSMTP), global (set for the account, written
// {{global.key}}) or template (a template’s own). A global variable that templates use but that has no
// value yet is listed without value; sends with those templates fail until you set it. A template
// variable lists in types every type its templates declare, and per template its type, required,
// default and unused (declared, but the source no longer names it).
func (s *VariablesService) List(ctx context.Context, opts ...RequestOption) (*Page[Variable], error) {
	return list[Variable](ctx, s.c, &request{method: http.MethodGet, path: "/variables"}, opts)
}

// ListAutoPaging is List as an iterator over every item of every page: it asks for the next page as
// the loop reaches it. Stop the loop to stop asking. An error ends the sequence.
func (s *VariablesService) ListAutoPaging(ctx context.Context, opts ...RequestOption) iter.Seq2[Variable, error] {
	return autoPaging(ctx, func() (*Page[Variable], error) { return s.List(ctx, opts...) })
}

// SetGlobal calls PUT /variables/global/{key}: Set a global variable.
//
// Create or replace a global variable. Every template that uses it renders the new value from the next
// send on. Requires a full-access live key; test keys get 403 test_key_restricted. The response does
// not list the templates using the variable; GET /variables does.
func (s *VariablesService) SetGlobal(ctx context.Context, key string, params *VariablesSetGlobalParams, opts ...RequestOption) (*Variable, error) {
	return call[Variable](ctx, s.c, &request{method: http.MethodPut, path: "/variables/global/{key}", pathArgs: []string{"key", key}, body: params}, opts)
}

// DeleteGlobal calls DELETE /variables/global/{key}: Delete a global variable.
//
// Delete a global variable. Sends with a template that still uses it then fail with 422
// template_render_error until it is set again. Requires a full-access live key; test keys get 403
// test_key_restricted.
func (s *VariablesService) DeleteGlobal(ctx context.Context, key string, opts ...RequestOption) (*Deleted, error) {
	return call[Deleted](ctx, s.c, &request{method: http.MethodDelete, path: "/variables/global/{key}", pathArgs: []string{"key", key}}, opts)
}
